#!/usr/bin/env python3
"""Generates supabase/migrations/0073_hrm_self_service.sql from hrms-v11.sql plus patched copies of four 0072 functions."""
import re, pathlib
S = pathlib.Path(__file__).resolve().parent; M = S.parent / 'supabase' / 'migrations'
api = (S / 'hrms-api.sql').read_text()

def fn(name):
    i = api.index('create or replace function ' + name + '(')
    j = api.index('$$;', api.index(' as $$', i) + 6) + 3
    k = api.find('\n', j); tail = api[j:k]
    return api[i:j]

def patch(text, pairs):
    for a, b in pairs:
        assert a in text, a[:80]
        text = text.replace(a, b, 1)
    return text

emp = patch(fn('console.hrms_emp_upsert'), [
 ("if pay not in ('monthly', 'daily') then raise exception 'Pay type must be monthly or daily.'; end if;",
  "if pay not in ('monthly', 'daily', 'fixed') then raise exception 'Pay type must be monthly, daily or fixed.'; end if;\n  if console.hrms_num(p, 'hours_per_day', 8) <= 0 or console.hrms_num(p, 'hours_per_day', 8) > 24 then raise exception 'Hours per day must be between 1 and 24.'; end if;"),
 ("pf, esi, pt, ot_eligible, uan, esi_no, pan, bank_name, bank_account, ifsc, notes)\n      values", "pf, esi, pt, ot_eligible, hours_per_day, bonus_eligible, uan, esi_no, pan, bank_name, bank_account, ifsc, notes)\n      values"),
 ("coalesce((p ->> 'ot_eligible')::boolean, false),\n              console.hrms_txt(p, 'uan')", "coalesce((p ->> 'ot_eligible')::boolean, false), console.hrms_num(p, 'hours_per_day', 8), coalesce((p ->> 'bonus_eligible')::boolean, false),\n              console.hrms_txt(p, 'uan')"),
 ("ot_eligible = case when p ? 'ot_eligible' then (p ->> 'ot_eligible')::boolean else ot_eligible end,",
  "ot_eligible = case when p ? 'ot_eligible' then (p ->> 'ot_eligible')::boolean else ot_eligible end,\n        hours_per_day = case when p ? 'hours_per_day' then console.hrms_num(p, 'hours_per_day', 8) else hours_per_day end, bonus_eligible = case when p ? 'bonus_eligible' then (p ->> 'bonus_eligible')::boolean else bonus_eligible end,"),
])
att = patch(fn('public.kmr_hrms_att_get'), [
 ("from console.hrms_leaves l where l.customer_id = cid and l.status = 'Approved' and l.from_date <= p_to and l.to_date >= p_from), '[]'),",
  "from console.hrms_leaves l where l.customer_id = cid and l.kind = 'leave' and l.status = 'Approved' and l.from_date <= p_to and l.to_date >= p_from), '[]'),\n"
  "    'permissions', coalesce((select jsonb_agg(jsonb_build_object('employee_id', l.employee_id, 'date', l.from_date, 'from_time', l.from_time, 'to_time', l.to_time, 'minutes', l.minutes)) from console.hrms_leaves l where l.customer_id = cid and l.kind = 'permission' and l.status = 'Approved' and l.from_date between p_from and p_to), '[]'),"),
])
dec = patch(fn('public.kmr_hrms_leave_decide'), [("if p_status in ('Approved', 'Cancelled', 'Rejected') then", "if p_status in ('Approved', 'Cancelled', 'Rejected') and l.kind = 'leave' then")])
head = "-- 0073: HRM & Payroll 1.1 - employee mobile access (ID + date of birth), permissions, hours per day, attendance bonus, fixed pay\n-- Generated by scripts/make-hrms-v11.py; run after 0072.\n\n"
out = head + (S / 'hrms-v11.sql').read_text().split('-- who may call what')[0] + "\n" + emp + "\nrevoke all on function console.hrms_emp_upsert(uuid, jsonb, text) from public, anon, authenticated;\n\n" + att + "\nrevoke all on function public.kmr_hrms_att_get(text, date, date) from public, anon;\ngrant execute on function public.kmr_hrms_att_get(text, date, date) to authenticated;\n\n" + dec + "\nrevoke all on function public.kmr_hrms_leave_decide(text, uuid, text) from public, anon;\ngrant execute on function public.kmr_hrms_leave_decide(text, uuid, text) to authenticated;\n\n-- who may call what" + (S / 'hrms-v11.sql').read_text().split('-- who may call what')[1]
(M / '0073_hrm_self_service.sql').write_text(out)
print('written', len(out), 'bytes')
